// #region 🔖Configuration
// [👤compose🖱️vscode⚙️viteconfig🔖configuration](repo://p/u/compose/b/u/vscode/f/vite.config.ts/s/Configuration)
// Vite build configuration for the compose VS Code extension.
// Configuration MUST output a CJS bundle targeting Node 18.

import mdx from "@mdx-js/rollup";
import react from "@vitejs/plugin-react";
import path from "path";
import rehypeAutolinkHeadings from "rehype-autolink-headings";
import rehypeSlug from "rehype-slug";
import remarkFrontmatter from "remark-frontmatter";
import remarkGfm from "remark-gfm";
import remarkMdxFrontmatter from "remark-mdx-frontmatter";
import { fileURLToPath } from "url";
import { defineConfig } from "vite";
import topLevelAwait from "vite-plugin-top-level-await";
import wasm from "vite-plugin-wasm";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export default defineConfig(async ({ mode }) => {
  // Webview build: produces sketchpad-dist/ with an HTML app for the VS Code webview.
  if (mode === "webview") {
    const tailwind = await import("@tailwindcss/vite");
    return {
      root: __dirname,
      plugins: [
        tailwind.default(),
        {
          ...mdx({
            remarkPlugins: [remarkGfm, remarkFrontmatter, remarkMdxFrontmatter],
            rehypePlugins: [rehypeSlug, rehypeAutolinkHeadings],
            providerImportSource: "@mdx-js/react",
          }),
          enforce: "pre" as const,
        },
        react(),
        wasm(),
        topLevelAwait(),
      ],
      build: {
        outDir: "sketchpad-dist",
        emptyOutDir: true,
        rollupOptions: {
          input: path.resolve(__dirname, "webview.html"),
          // Externalize massive benchmark/test JSON assets and node-only modules
          // that leak into the bundle via @semio-tech/compose-js barrel imports.
          external: [/kit_metabolism/, /metabolism\.kit/, /kit_metabolism_diffed/, /diff_kit_metabolism/, /kit_invalid/],
          plugins: [
            {
              name: "externalize-benchmark-assets",
              resolveId(source: string) {
                // Stub out benchmark JSON assets that would bloat the webview bundle.
                if (/kit_metabolism|metabolism\.kit|kit_metabolism_diffed|diff_kit_metabolism|kit_invalid/.test(source)) {
                  return { id: source, external: true };
                }
                return null;
              },
            },
          ],
        },
        target: "esnext",
        sourcemap: true,
        minify: false,
      },
      resolve: {
        alias: {
          "@semio-tech/compose-sketchpad": path.resolve(__dirname, "../sketchpad"),
          "@compose/studio": path.resolve(__dirname, "../studio/studio.ts"),
          "@semio-tech/compose-js": path.resolve(__dirname, "../js"),
          "@elements/ui": path.resolve(__dirname, "../../elements/ui"),
          "@semio-tech/compose-assets": path.resolve(__dirname, "../assets"),
        },
      },
    };
  }

  // Extension host build: produces out/extension.js targeting Node 18.
  return {
    build: {
      lib: {
        entry: path.resolve(__dirname, "extension.ts"),
        formats: ["cjs"],
        fileName: () => "extension",
      },
      rollupOptions: {
        external: ["vscode"],
        output: {
          entryFileNames: "extension.js",
          format: "cjs",
          sourcemap: true,
        },
      },
      outDir: "out",
      emptyOutDir: true,
      minify: false,
      sourcemap: true,
      target: "node18",
      ssr: true,
    },
    ssr: {
