        },
        target: "esnext",
        sourcemap: true,
        minify: false,
      },
      resolve: {
        alias: {
          "@semio-tech/compose-sketchpad": path.resolve(__dirname, "../sketchpad"),
          "@compose/studio": path.resolve(__dirname, "../studio/studio.ts"),
          "@semio-tech/compose-js": path.resolve(__dirname, "../js"),
          "@elements/ui": path.resolve(__dirname, "../../elements/ui"),
