      },
    };
  }

  // Extension host build: produces out/extension.js targeting Node 18.
  return {
    build: {
      lib: {
        entry: path.resolve(__dirname, "extension.ts"),
        formats: ["cjs"],
        fileName: () => "extension",
      },
      rollupOptions: {
        external: ["vscode"],
        output: {
          entryFileNames: "extension.js",
          format: "cjs",
          sourcemap: true,
        },
      },
      outDir: "out",
      emptyOutDir: true,
      minify: false,
      sourcemap: true,
      target: "node18",
      ssr: true,
    },
    ssr: {
      noExternal: true,
    },
  };
});
// #endregion 🔖Configuration

