		} else if (uri.startsWith('data:model/gltf-binary')) {
			return 'glb';
		} else if (uri.startsWith('data:application/')) {
			return 'bin';
		}
		return uri.split(/[\\/]/).pop()!.split(/[.]/).pop()!;
	}
